struct SqlError: Error {
    let reason: String
}

func fail(_ s: String) throws -> Never {
    throw SqlError(reason:s)
}

enum Value: Hashable {
    case null, int(Int64), text(String)
    var type: String {
        switch self {
            case .null: return "NULL"
            case .int: return "INT"
            case .text: return "TEXT"
        }
    }
    var written: String {
        switch self {
            case .null: return "NULL"
            case .int(let n): return String(n)
            case .text(let s): return s
        }
    }
    var integer: Int64 {
        if case .int(let n) = self {
            return n
        }
        return 0
    }
    var truth: Bool {
        self != .null && integer != 0
    }
}
struct Column {
    let name: String
    let type: String
    let notNull: Bool
    let keys: Int
}

struct Table {
    let name: String
    let columns: [Column]
    var rows: [[Value]] = []
    var primary: Int? {
        columns.firstIndex {
            $0.keys > 0
        }
    }
}
